/** Domain-level fallback used when no keyword matches. Keyed by domain id across all certs. */
// Every id here must exist in videoCatalog for the matching cert.
const domainFallback: Record<string, string> = {
  "cloud-concepts": "N0SYCyS2xZA",
  "security-and-compliance": "crBcr6Nobs8",
  "cloud-technology-and-services": "BtJAsvJOlhM",
  "billing-pricing-and-support": "op_9NfAVedY",
  "ai-ml-fundamentals": "EhExK4JgXvE",
  "genai-fundamentals": "qWSFcRXpjxQ",
  "foundation-model-applications": "mhItmKsB5tQ",
  "responsible-ai": "1zf_ofk6HSs",
  "ai-security-governance": "CenD1dq3xj8",
};

export function videoUrlFor(id: string): string {
  return `https://www.youtube.com/watch?v=${id}`;
}

export function isOfficialAws(entry: Pick<VideoEntry, "channelId">): boolean {
  return entry.channelId === OFFICIAL_AWS_CHANNEL_ID;
}

/**
 * Catalog rules: the length cap, well-formed metadata, no video listed twice for one cert
 * (the same video may serve both certs), and a fallback for every domain that exists in that
 * domain's cert catalog. Returns every problem found, so tests can assert on them.
 */
export function videoCatalogProblems(
  catalog: VideoEntry[],
  fallback: Record<string, string>,
  certs: Pick<Certification, "id" | "domains">[]
): string[] {
  const problems: string[] = [];
  const seen = new Set<string>();
  for (const v of catalog) {
    const key = `${v.cert}/${v.id}`;
    if (seen.has(key)) problems.push(`${v.cert}: duplicate video ${v.id}`);
    seen.add(key);
    if (!Number.isInteger(v.seconds) || v.seconds <= 0) problems.push(`video ${v.id}: seconds must be a positive whole number`);
    if (!/^UC[\w-]{22}$/.test(v.channelId)) problems.push(`video ${v.id}: channelId ${v.channelId} is not a YouTube channel id`);
    if (v.seconds > MAX_VIDEO_SECONDS && !isOfficialAws(v)) {
      problems.push(`video ${v.id} (${v.label}): ${v.seconds}s is over the ${MAX_VIDEO_SECONDS}s cap and not from the official AWS channel`);
    }
  }
  for (const cert of certs) {
    for (const d of cert.domains) {
      const id = fallback[d.id];
      if (!catalog.some((v) => v.cert === cert.id && v.id === id)) {
        problems.push(`domain ${d.id}: fallback video ${id} is not in the ${cert.id} catalog`);
      }
    }
  }
  return problems;
}

/**
 * Picks the best curated video for a question, in priority order:
 * 1. an explicit `videoUrl` on the question;
 * 2. the reviewed assignment generated by `scripts/assign-videos.mts`, which scores every
 *    question against the whole catalog with keyword-rarity weighting and spreads questions
 *    across videos so few share a link;
 * 3. live keyword scoring, for questions added since the assignments were last generated;
 * 4. a domain-level video, so every question has a link.
 */
export function catalogFor(certId: CertificationId): VideoEntry[] {
  return videoCatalog.filter((v) => v.cert === certId);
}

export function resolveVideo(question: Question, certId: CertificationId): { url: string; label: string } {
  if (question.videoUrl) {
    return { url: question.videoUrl, label: question.videoLabel ?? "YouTube" };
  }

  const catalog = catalogFor(certId);
  if (catalog.length === 0) {
    const query = encodeURIComponent(`AWS ${question.text.slice(0, 80)}`);
    return { url: `https://www.youtube.com/results?search_query=${query}`, label: "Search YouTube" };
  }

  const assignedId = videoAssignments[question.id];
  const assigned = assignedId ? catalog.find((v) => v.id === assignedId) : undefined;
  if (assigned) {
    return { url: videoUrlFor(assigned.id), label: assigned.label };
  }

  const haystacks = haystacksFor(question);
  let best: VideoEntry | undefined;
  let bestScore = 0;

  for (const entry of catalog) {
    const score = entryScore(entry, haystacks);
    if (score > bestScore) {
      bestScore = score;
      best = entry;
    }
  }

  const fallbackId = domainFallback[question.domain];
  const chosen = best ?? catalog.find((v) => v.id === fallbackId) ?? catalog[0];
  return { url: videoUrlFor(chosen.id), label: chosen.label };
}
